 const label=k=>{if(titles[k])return t(...titles[k]);const definition=[...Object.values(GAME_ACCOUNT_FIELDS),...Object.values(LISTING_TYPE_FIELDS)].flat().find(v=>v[0]===k);return definition?t(...definition.slice(1,4)):k.replaceAll('_',' ')};
 let chatTimer=0,epoch=0,lastForm=null,lastSubmit=0,collectionUser='',preferences=null,browserAsked=false;
