 function fail(form,error){if(!form?.isConnected)return;form.querySelectorAll('.ex-form-error').forEach(n=>n.remove());const box=document.createElement('p');box.className='notice error ex-form-error';box.setAttribute('role','alert');box.textContent=localized(error.message);form.prepend(box);const fields=Object.keys(error.fields||{});for(const key of fields){const aliases={'Sarlavha':'title','Tavsif':'description','Narx':'price_minor','Qoldiq':'stock','Hudud':'region','Platforma':'platform','Yetkazish muddati':'delivery_eta','O‘yin yoki platforma':'game_name','Talablar':'requirements','Ism':'name','Email':'email'};const input=form.elements.namedItem(aliases[key]||key)||[...form.querySelectorAll('input,textarea,select')].find(i=>i.closest('label,.field')?.textContent.toLowerCase().includes(key.toLowerCase()));if(!input)continue;input.setAttribute('aria-invalid','true');const note=document.createElement('small');note.className='ex-form-error';note.id='ex-error-'+key;note.textContent=localized(error.fields[key]);input.setAttribute('aria-describedby',note.id);input.after(note)}}
 function bind(form,fn){if(!form)return;form.addEventListener('submit',async event=>{event.preventDefault();const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await fn(Object.fromEntries(new FormData(form)),form,event.submitter)}catch(error){fail(form,error)}finally{buttons.forEach(b=>b.disabled=false)}})}
