 function errorFromApi(error){if(lastForm?.id==='auth-form'||lastForm?.matches('.topup-admin-create,.topup-admin-save,.topup-stock-adjust,.topup-supplier-map'))return;if(lastForm&&Date.now()-lastSubmit<30000)fail(lastForm,error)}
