  const update=()=>{const count=Number(quantity.value),valid=canBuy&&quantity.validity.valid,total=fmt(LaunchUX.price(it,Number.isFinite(count)&&count>=min?count:min)*(Number.isFinite(count)&&count>=min?count:min),it.currency);const price=app.querySelector('[data-listing-price]');if(price)price.textContent=total;buybar.querySelector('#ex-mobile-amount').textContent=total;buybar.querySelector('[data-mobile-count]').textContent=canBuy?quantity.value:t('Mavjud emas','Нет в наличии','Unavailable');app.querySelectorAll('[data-action="buy-now"]').forEach(button=>button.disabled=!valid);controls.querySelector('[data-quantity-unit]').textContent=count>1?`${count} × ${fmt(LaunchUX.price(it,count),it.currency)} / ${unit(it)}`:`${t('Birlik uchun','За единицу','Per')} ${unit(it)}${min>1?' · '+t('Kamida','Минимум','Minimum')+' '+min:''}`;controls.querySelector('[data-quantity-step="-1"]').disabled=!canBuy||count<=min;controls.querySelector('[data-quantity-step="1"]').disabled=!canBuy||count>=max;};
