  if(me&&it.status==='published'){const scale=it.currency==='UZS'?1:100;const watch=document.createElement('details');watch.className='ex-price-watch';watch.innerHTML=`<summary>${t('Narx pasayishini kuzatish','Следить за снижением цены','Watch for a price drop')}</summary><form>${field('target_price',t('Maqsad narx','Целевая цена','Target price')+' ('+s(it.currency)+')','number','',`min="${1/scale}" max="${1000000000000/scale}" step="${1/scale}" required placeholder="${(it.price_minor/scale).toFixed(scale===100?2:0)}"`)}${submit(t('Saqlash','Сохранить','Save alert'))}</form>`;(app.querySelector('.listing-purchase-panel')||right).append(watch);bind(watch.querySelector('form'),async d=>{await api('/price-watches/'+e(it.id),{method:'POST',body:values({target_minor:Math.round(Number(d.target_price)*scale)})});toast(t('Narx kuzatilmoqda','Цена отслеживается','Price watch saved'))})}
