 function checkoutContext(validate=true){const context={};const normalized=v=>String(v||'').toLowerCase().trim(),aliases={uz:'uzbekistan',us:'united states',usa:'united states',ru:'russia',eu:'europe'};const norm=v=>aliases[normalized(v)]||normalized(v);let invalid=false;for(const section of app.querySelectorAll('[data-compat-item]')){const platform=section.querySelector('[name=buyer_platform]'),region=section.querySelector('[name=buyer_region]');if(validate&&(!platform.reportValidity()||!region.reportValidity()))invalid=true;context[section.dataset.compatItem]={platform:platform.value.trim(),region:region.value.trim()};const mismatches=[];for(const [key,input]of [['platform',platform],['region',region]]){const expected=section.dataset[key],choices=expected.split(/[,;/|]/).map(norm);if(input.value&&expected&&!['global','all','any','all regions','worldwide'].includes(norm(expected))&&!choices.includes(norm(input.value)))mismatches.push(label(key))}const warning=section.querySelector('.ex-compat-warning');warning.hidden=!mismatches.length;if(mismatches.length){warning.textContent=t('Mos kelmayapti: ','Не совпадает: ','Does not match: ')+mismatches.join(', ')+'. '+t('Davom etishdan oldin mos mahsulot tanlang yoki sotuvchidan aniqlang.','До оформления выберите подходящий товар или уточните у продавца.','Choose a compatible product or confirm with the seller before ordering.');invalid=true}}if(validate&&invalid)throw Error(t('Platforma va hudud mosligini tekshiring.','Проверьте платформу и регион.','Check the platform and region compatibility.'));return context}
