  bind(app.querySelector('.ex-message-search'),async d=>{search=d.q;const r=await api('/conversations/'+e(selected)+'?q='+e(search));before=r.next_before;hasMore=r.has_more;draw(mark(r),true)});app.querySelector('[data-clear]').onclick=async()=>{search='';app.querySelector('.ex-message-search input').value='';const r=await api('/conversations/'+e(selected));before=r.next_before;hasMore=r.has_more;draw(mark(r),true)};
