  const oldSubmit=async event=>{event.preventDefault();if(!input.value.trim())return;const button=form.querySelector('button');button.disabled=true;draft.sentBody=input.value.trim();saveDraft();try{await api('/conversations/'+e(selected)+'/messages',{method:'POST',body:values({body:input.value.trim(),request_key:draft.key})});input.value='';draft={body:'',key:crypto.randomUUID()};sessionStorage.removeItem(draftKey);$('#ex-message-error').textContent='';clearTimeout(chatTimer);await refresh()}catch(error){$('#ex-message-error').textContent=error.message+' · '+t('Matn saqlandi. Yuborishni qayta bosing.','Текст сохранён. Нажмите отправить ещё раз.','Your draft is saved. Press send to retry.')}finally{button.disabled=false}};form.onsubmit=oldSubmit;
