 async function browserAlerts(rows){if(!me||document.visibilityState!=='hidden'||!('Notification'in window)||Notification.permission!=='granted')return;if(!preferences)preferences=await api('/experience/settings');if(!preferences.browser)return;let shown=[];try{shown=JSON.parse(sessionStorage.getItem('sentryloot_shown_notifications_'+me.id)||'[]')}catch{}for(const r of rows.filter(r=>!r.read_at&&!shown.includes(r.id)).slice(0,3)){const n=new Notification(localized(r.title),{body:t('Tafsilotlar SentryLoot hisobingizda.','Подробности в аккаунте SentryLoot.','See details in your SentryLoot account.'),icon:'https://images.gamestorehub.com/site-assets/sentryloot-app-icon.png',tag:r.id});n.onclick=()=>{window.focus();location.hash=notificationRoute(r.href);n.close()};shown.push(r.id)}sessionStorage.setItem('sentryloot_shown_notifications_'+me.id,values(shown.slice(-100)))}
